def fizzbuzz(n):
    """
    Returns the FizzBuzz string for a given number n.

    - Returns "FizzBuzz" if n is divisible by both 3 and 5
    - Returns "Fizz" if n is divisible by 3
    - Returns "Buzz" if n is divisible by 5
    - Returns the number as a string otherwise
    """
    if n % 15 == 0:
        return "FizzBuzz"
    elif n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    else:
        return str(n)


def fizzbuzz_range(start, end):
    """
    Returns a list of FizzBuzz strings for numbers in range [start, end].
    """
    return [fizzbuzz(i) for i in range(start, end + 1)]


